                <div class="subject-benefit__seats"><el-input-number :model-value="draft.account_limit" :min="1" :max="99999" :precision="0" controls-position="right" :disabled="draft.unlimited" aria-label="总账号数，包含负责人" @update:model-value="patch('account_limit',$event)" /><span>人，包含负责人</span><el-checkbox :model-value="draft.unlimited" @update:model-value="patch('unlimited',$event)">不限人数</el-checkbox></div>
            </div>
            <div class="subject-benefit__section">
                <h4>协作权限</h4>
                <div class="subject-benefit__rights"><el-checkbox v-for="(label,key) in subjectCapabilityLabels" :key="key" :model-value="draft[key]" @update:model-value="patch(key,$event)">{{ label }}</el-checkbox></div>
            </div>
