<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { ElMessageBox } from 'element-plus'
import { Delete, Plus } from '@element-plus/icons-vue'
import UploadImage from '@/components/upload-image/index.vue'
import { img } from '@/utils/common'
import { normalizeSubjectBenefit, subjectBenefitError, subjectBenefitPayload, subjectCapabilityLabels,subjectVisualPresets,subjectVisualPresetColors,subjectVisualPreview,subjectCoverThemes,subjectCoverPath,subjectCoverSelection,type SubjectVisual,type SubjectBenefit, type SubjectCycle } from '../../../composables/entity'

const props=defineProps<{modelValue?:Record<string,any>}>()
const emit=defineEmits<{(event:'update:modelValue',value:SubjectBenefit):void}>()
const draft=ref<SubjectBenefit>(normalizeSubjectBenefit(props.modelValue)),error=ref(''),errorRef=ref<any>()
const visualPresetChoice=ref(draft.value.visual.preset)
const coverFormat=ref('png')
const visualFields=[{key:'start_color',label:'渐变起色'},{key:'end_color',label:'渐变止色'},{key:'text_color',label:'卡面文字'},{key:'accent_color',label:'标识强调色'}] as const
const visualPreview=computed(()=>subjectVisualPreview(draft.value.visual))
const visualPreviewStyle=computed(()=>({backgroundImage:`linear-gradient(${visualPreview.value.angle}deg,${visualPreview.value.start_color},${visualPreview.value.end_color})`,color:visualPreview.value.text_color,'--member-accent':visualPreview.value.accent_color}))
const visualPreviewImage=computed(()=>visualPreview.value.card_image?img(visualPreview.value.card_image):'')
let dirty=false,lastEmitted='',customSequence=0
watch(()=>props.modelValue,value=>{const incoming=JSON.stringify(value||{});if(incoming===lastEmitted)return;if(!dirty)draft.value=normalizeSubjectBenefit(value)},{deep:true})
watch(()=>draft.value.visual.preset,value=>{visualPresetChoice.value=value})
function publish(){dirty=true;error.value='';const value=subjectBenefitPayload(draft.value);lastEmitted=JSON.stringify(value);emit('update:modelValue',value)}
function patch(key:keyof Omit<SubjectBenefit,'cycles'>,value:any){draft.value={...draft.value,[key]:value,...(key==='experience_gate_enabled'&&value===false?{experience_purchase_enabled:false,experience_unit_price:'0.00'}:{})};publish()}
function patchVisual(key:keyof SubjectVisual,value:any){draft.value={...draft.value,visual:{...draft.value.visual,[key]:value,...(visualFields.some(field=>field.key===key)?{preset:'custom'}:{})}};publish()}
function applyVisualPreset(){const preset=visualPresetChoice.value;if(!subjectVisualPresets.some(item=>item.key===preset))return;const colors=preset==='auto'?{start_color:'',end_color:'',text_color:'',accent_color:''}:subjectVisualPresetColors[preset]||{};draft.value={...draft.value,visual:{...draft.value.visual,...colors,preset}};publish()}
function applyCover(theme:string){const visual=subjectCoverSelection(draft.value.visual,theme,coverFormat.value);if(!visual)return;draft.value={...draft.value,visual};publish()}
function patchCycle(index:number,key:keyof SubjectCycle,value:any){draft.value={...draft.value,cycles:draft.value.cycles.map((row,i)=>i===index?{...row,[key]:value}:row)};publish()}
function isPreset(key:string){return['month','quarter','year'].includes(key)}
function addCycle(){if(draft.value.cycles.length>=50)return;let key='';do{key=`cycle_${(++customSequence).toString(36)}`}while(draft.value.cycles.some(row=>row.key===key));draft.value.cycles=[...draft.value.cycles,{key,name:'自定义周期',months:1,enabled:false,price:'0.00'}];publish()}
async function removeCycle(index:number){const cycle=draft.value.cycles[index];if(!cycle||isPreset(cycle.key))return;try{await ElMessageBox.confirm(`移除“${cycle.name||'自定义周期'}”后，商户不能再购买此周期；已付订单与有效期不变。保存会员等级后生效。`,'移除购买周期',{confirmButtonText:'确认移除',cancelButtonText:'取消',type:'warning'})}catch{return}draft.value.cycles=draft.value.cycles.filter(row=>row.key!==cycle.key);publish()}
async function verify(){error.value=subjectBenefitError(draft.value);if(error.value){await nextTick();errorRef.value?.$el?.scrollIntoView?.({block:'center',behavior:'smooth'});return false}const value=subjectBenefitPayload(draft.value);lastEmitted=JSON.stringify(value);emit('update:modelValue',value);return true}
defineExpose({verify})
</script>
